	n := ni()
	s := ns()
	r := 0

	for i := 1; i < n; i++ {
		if s[i] == s[i-1] {
			r++
		}
	}

	printInt(r)
}

func ni() int {
	num := 0
	minus := false
	b := readByte()
	for b != -1 && !(b >= '0' && b <= '9' || b == '-') {
		b = readByte()
	}
	if b == '-' {
		minus = true
		b = readByte()
	}
	for {
		if b >= '0' && b <= '9' {
			num = num*10 + (b - '0')
		} else {
			if minus {
				return -num
			}
			return num
		}
		b = readByte()
	}
}

func ns() string {
	b := skip()
	buf := make([]byte, 0, 1024)
	for b != -1 && !isSpaceChar(b) {
		buf = append(buf, byte(b))
		b = readByte()
	}
	return string(buf)
}

func isSpaceChar(c int) bool {
	return !(c >= 33 && c <= 126)
}

func skip() int {
	b := readByte()
	for b != -1 && isSpaceChar(b) {
		b = readByte()
	}
	return b
}

