	b, err := reader.ReadByte()
	if err != nil {
		return -1
	}
	return int(b)
}

func printInt(n int) {
	writer.WriteString(intToString(n))
	writer.WriteByte('\n')
}

func intToString(n int) string {
	if n == 0 {
		return "0"
	}
	minus := false
	if n < 0 {
		minus = true
		n = -n
	}
	buf := make([]byte, 0, 20)
	for n > 0 {
		buf = append(buf, byte('0'+n%10))
		n /= 10
	}
	if minus {
		buf = append(buf, '-')
	}
	for i, j := 0, len(buf)-1; i < j; i, j = i+1, j-1 {
		buf[i], buf[j] = buf[j], buf[i]
	}
	return string(buf)
}
