func itoa(num int) string {
	if num == 0 {
		return "0"
	}
	neg := false
	if num < 0 {
		neg = true
		num = -num
	}
	var digits []byte
	for num > 0 {
		digits = append([]byte{byte('0' + num%10)}, digits...)
		num /= 10
	}
	if neg {
		digits = append([]byte{'-'}, digits...)
	}
	return string(digits)
}

func readByte() (int, error) {
	b, err := reader.ReadByte()
	if err != nil {
		return -1, err
	}
	return int(b), nil
}

